
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pw91_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pw91", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.027535285862398e-02, -6.929888351551473e-02, -6.789761471812131e-02, -6.588856611323368e-02, -6.301184012559395e-02, -5.890133305531450e-02, -5.305348674816741e-02, -4.483369354129981e-02, -3.374706745929500e-02, -2.104303395796830e-02, -1.492818595416270e-02, -3.932129992198916e-02, -4.634756135019048e-02, -3.300471184756112e-02, -1.735361953968997e-02, -4.285352901525673e-03, -2.300734272774320e-04, -1.955574459149040e-06, -1.924195073243490e-09, -7.505811032702759e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


